def cell_line(c1, r1, c2, r2):
    """Fill all cells on line from (c1,r1) to (c2,r2)"""
    dx = c2 - c1
    dy = r2 - r1
    steps = max(abs(dx), abs(dy))
    if steps == 0:
        return [(c1, r1)]

    cells = []
    for i in range(steps + 1):
        c = c1 + i * dx / steps
        r = r1 + i * dy / steps
        cells.append((round(c), round(r)))
    return cells

